export const tasks: Task[] = rows.map(
  ([id, title, status, priority, owner, effort, created, project, blockedBy = [], blocking = [], parent, due]) => ({
    id,
    url: `https://www.notion.so/${id}`,
    title,
    status,
    priority,
    owner,
    effort,
    due: due ?? null,
    notes: "",
    createdTime: created,
    projectIds: [project],
    blockedByIds: blockedBy,
    blockingIds: blocking,
    parentIds: parent ? [parent] : [],
    subtaskIds: [],
  }),
);

// Fill Sub-tasks from Parent task, the way Notion's paired relation does.
for (const t of tasks) {
  for (const p of t.parentIds) tasks.find((x) => x.id === p)!.subtaskIds.push(t.id);
}
